  ["Codex learns what your turn-ins really give, and who took each writ, so the guides' numbers are replaced as you play."] = "Codex aprende lo que dan de verdad tus entregas y quién aceptó cada encargo, así que las cifras de las guías se sustituyen mientras juegas.",
  ["%s Merchant's Favor."] = "%s de Favor de mercader.",
  ["(yours: counted in)"] = "(tuyo: incluido)",
  ["(not taken)"] = "(no elegido)",
  ["Legacy talents: %s."] = "Talentos de legado: %s.",
  ["Learned from your turn-ins: %d crate kinds, %d writs, %d writ NPCs."] = "Aprendido de tus entregas: %d tipos de caja, %d encargos, %d PNJ de encargos.",
  ["Prices: %s."] = "Precios: %s.",
  ["the Auction House module is off, so writs have no prices"] = "el módulo Casa de subastas está desactivado, así que los encargos no tienen precio",
  ["learned turn-in amounts cleared; the guides' numbers are used again."] = "cantidades aprendidas borradas; se vuelven a usar las cifras de las guías.",
  ["Open the window"] = "Abrir la ventana",
  ["Reputation, Merchant's Favor, your writs by who takes them, the next standings and the cheapest reputation (%s)."] = "Reputación, Favor de mercader, tus encargos por quién los acepta, los siguientes rangos y la reputación más barata (%s).",
  ["The cheapest writs to your next standing, and the items they ask for, in the Codex shopping list \"%s\" (%s)."] = "Los encargos más baratos hasta tu siguiente rango, y los objetos que piden, en la lista de compra de Codex «%s» (%s).",
  ["Forget what was learned"] = "Olvidar lo aprendido",
  ["Codex remembers the Merchant's Favor and reputation each crate and writ gave you. Clear them to go back to the guides' numbers. Who takes each writ is kept."] = "Codex recuerda el Favor de mercader y la reputación que te dio cada caja y cada encargo. Bórralos para volver a las cifras de las guías. Quién acepta cada encargo se conserva.",
  ["How it works"] = "Cómo funciona",
  ["Commerce commands:"] = "Comandos de Commerce:",
  ["show or hide the window"] = "muestra u oculta la ventana",
  ["every NPC who takes writs, with all its writs and which you have"] = "cada PNJ que acepta encargos, con todos sus encargos y cuáles tienes",
  ["Codex shopping list of the cheapest writs to your next standing"] = "lista de compra de Codex con los encargos más baratos hasta tu siguiente rango",
  ["this module's page in the Codex window"] = "la página de este módulo en la ventana de Codex",
  ["what Codex sees (faction, Favor, prices, bags)"] = "lo que ve Codex (facción, Favor, precios, bolsas)",
  ["Craftsman's Writs and Waylaid Crates: auction prices, reputation, Merchant's Favor, who takes each writ and the cheapest writs to buy."] = "Encargos de artesano y cajas extraviadas: precios de subasta, reputación, Favor de mercader, quién acepta cada encargo y los encargos más baratos para comprar.",
  ["west of %s, %s"] = "al oeste de %s, %s",
})

